-- ETAPA 22: restricted contractor portal. Portal users are never organization members.
create table public.contractor_organizations (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,legal_name text not null check(btrim(legal_name)<>''),tax_id text,kind text not null default 'contractor' check(kind in ('contractor','supplier')),status text not null default 'pending' check(status in ('pending','approved','suspended','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,tax_id));
create table public.contractor_contacts (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,contractor_organization_id uuid not null references public.contractor_organizations(id) on delete restrict,user_id uuid references auth.users(id) on delete set null,email text not null check(position('@' in email)>1),name text not null check(btrim(name)<>''),status text not null default 'invited' check(status in ('invited','active','inactive')),created_at timestamptz not null default now(),unique(organization_id,email));
create table public.contracts (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,contractor_organization_id uuid not null references public.contractor_organizations(id) on delete restrict,code text not null check(btrim(code)<>''),title text not null check(btrim(title)<>''),starts_at date not null,ends_at date,requirement_id uuid references public.requirements(id) on delete restrict,status text not null default 'draft' check(status in ('draft','pending_approval','active','suspended','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at is null or ends_at>=starts_at),unique(organization_id,code));
create table public.contract_site_accesses (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,contract_id uuid not null references public.contracts(id) on delete restrict,site_id uuid not null references public.sites(id) on delete restrict,status text not null default 'pending' check(status in ('pending','approved','revoked')),approved_at timestamptz,approved_by uuid references auth.users(id) on delete set null,unique(contract_id,site_id));
create table public.contractor_workers (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,contractor_organization_id uuid not null references public.contractor_organizations(id) on delete restrict,display_name text not null check(btrim(display_name)<>''),external_reference text,site_id uuid references public.sites(id) on delete set null,status text not null default 'active' check(status in ('active','inactive')),created_at timestamptz not null default now(),unique(contractor_organization_id,external_reference));
create table public.contract_document_requirements (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,contract_id uuid not null references public.contracts(id) on delete restrict,requirement_id uuid references public.requirements(id) on delete restrict,title text not null check(btrim(title)<>''),due_at date,required boolean not null default true,status text not null default 'active' check(status in ('active','waived','archived')),created_at timestamptz not null default now());
create table public.contract_document_submissions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,contract_document_requirement_id uuid not null references public.contract_document_requirements(id) on delete restrict,document_version_id uuid not null references public.document_versions(id) on delete restrict,status text not null default 'submitted' check(status in ('submitted','approved','rejected','expired')),submitted_at timestamptz not null default now(),reviewed_at timestamptz,reviewed_by uuid references auth.users(id) on delete set null,review_note text,unique(contract_document_requirement_id,document_version_id));
create table public.contract_evaluations (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,contract_id uuid not null references public.contracts(id) on delete restrict,status text not null default 'draft' check(status in ('draft','approved','rejected')),score numeric(5,2) check(score is null or (score>=0 and score<=100)),notes text,evaluated_at timestamptz,evaluated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.contractor_portal_accesses (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,contractor_contact_id uuid not null references public.contractor_contacts(id) on delete restrict,contract_id uuid not null references public.contracts(id) on delete restrict,site_id uuid references public.sites(id) on delete restrict,status text not null default 'invited' check(status in ('invited','active','revoked')),created_at timestamptz not null default now(),unique(contractor_contact_id,contract_id,site_id));
create index contracts_org_contractor_idx on public.contracts(organization_id,contractor_organization_id,status); create index contractor_contacts_user_idx on public.contractor_contacts(user_id,status); create index portal_access_user_idx on public.contractor_portal_accesses(contractor_contact_id,status); create index contractor_workers_org_contractor_idx on public.contractor_workers(organization_id,contractor_organization_id); create index contract_requirements_contract_idx on public.contract_document_requirements(contract_id,due_at); create index contract_submissions_requirement_idx on public.contract_document_submissions(contract_document_requirement_id,status);
insert into public.permissions(code,module,action,description) values ('contractors.read','contractors','read','Consultar contratistas y contratos.'),('contractors.manage','contractors','manage','Gestionar contratistas, contratos y requisitos documentales.'),('contractors.approve','contractors','approve','Aprobar accesos, documentos y evaluaciones de contratistas.') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.code in ('contractors.read','contractors.manage','contractors.approve') where r.code='organization_admin' and r.organization_id is null on conflict do nothing;
create or replace function private.is_contractor_portal_user(p_organization_id uuid,p_contract_id uuid) returns boolean language sql security definer set search_path='' stable as $$ select exists(select 1 from public.contractor_portal_accesses a join public.contractor_contacts c on c.id=a.contractor_contact_id where a.organization_id=p_organization_id and a.contract_id=p_contract_id and a.status='active' and c.status='active' and c.user_id=(select auth.uid())) $$;
create or replace function private.validate_contractor_links() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if tg_table_name='contracts' and not exists(select 1 from public.contractor_organizations where id=new.contractor_organization_id and organization_id=new.organization_id) then raise exception 'contractor belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='contract_site_accesses' and (not exists(select 1 from public.contracts where id=new.contract_id and organization_id=new.organization_id) or not exists(select 1 from public.sites where id=new.site_id and organization_id=new.organization_id)) then raise exception 'contract site belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='contractor_workers' and (not exists(select 1 from public.contractor_organizations where id=new.contractor_organization_id and organization_id=new.organization_id) or (new.site_id is not null and not exists(select 1 from public.sites where id=new.site_id and organization_id=new.organization_id))) then raise exception 'contractor worker belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='contract_document_requirements' and not exists(select 1 from public.contracts where id=new.contract_id and organization_id=new.organization_id) then raise exception 'contract document requirement belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='contract_document_submissions' and (not exists(select 1 from public.contract_document_requirements r where r.id=new.contract_document_requirement_id and r.organization_id=new.organization_id) or not exists(select 1 from public.document_versions d where d.id=new.document_version_id and d.organization_id=new.organization_id)) then raise exception 'contract document belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='contract_evaluations' and not exists(select 1 from public.contracts where id=new.contract_id and organization_id=new.organization_id) then raise exception 'contract evaluation belongs to another organization' using errcode='23514'; end if;
 if tg_table_name='contractor_portal_accesses' and (not exists(select 1 from public.contractor_contacts c join public.contracts k on k.contractor_organization_id=c.contractor_organization_id where c.id=new.contractor_contact_id and c.organization_id=new.organization_id and k.id=new.contract_id and k.organization_id=new.organization_id) or (new.site_id is not null and not exists(select 1 from public.contract_site_accesses where contract_id=new.contract_id and site_id=new.site_id and organization_id=new.organization_id and status='approved'))) then raise exception 'portal access scope is invalid' using errcode='23514'; end if; return new; end; $$;
revoke all on function private.is_contractor_portal_user(uuid,uuid),private.validate_contractor_links() from public,anon,authenticated,service_role;
alter table public.contractor_organizations enable row level security; alter table public.contractor_contacts enable row level security; alter table public.contracts enable row level security; alter table public.contract_site_accesses enable row level security; alter table public.contractor_workers enable row level security; alter table public.contract_document_requirements enable row level security; alter table public.contract_document_submissions enable row level security; alter table public.contract_evaluations enable row level security; alter table public.contractor_portal_accesses enable row level security;
grant select,insert,update on public.contractor_organizations,public.contractor_contacts,public.contracts,public.contract_site_accesses,public.contractor_workers,public.contract_document_requirements,public.contract_document_submissions,public.contract_evaluations,public.contractor_portal_accesses to authenticated;
create policy contractors_internal on public.contractor_organizations for all to authenticated using((select private.has_permission(organization_id,'contractors.manage'))) with check((select private.has_permission(organization_id,'contractors.manage'))); create policy contractors_read on public.contractor_organizations for select to authenticated using((select private.has_permission(organization_id,'contractors.read')));
create policy contractor_contacts_internal on public.contractor_contacts for all to authenticated using((select private.has_permission(organization_id,'contractors.manage'))) with check((select private.has_permission(organization_id,'contractors.manage')));
create policy contracts_internal on public.contracts for all to authenticated using((select private.has_permission(organization_id,'contractors.manage'))) with check((select private.has_permission(organization_id,'contractors.manage'))); create policy contracts_read on public.contracts for select to authenticated using((select private.has_permission(organization_id,'contractors.read')) or (select private.is_contractor_portal_user(organization_id,id)));
create policy contractor_site_internal on public.contract_site_accesses for all to authenticated using((select private.has_permission(organization_id,'contractors.manage'))) with check((select private.has_permission(organization_id,'contractors.manage'))); create policy contractor_workers_internal on public.contractor_workers for all to authenticated using((select private.has_permission(organization_id,'contractors.manage'))) with check((select private.has_permission(organization_id,'contractors.manage')));
create policy contractor_requirements_read on public.contract_document_requirements for select to authenticated using((select private.has_permission(organization_id,'contractors.read')) or (select private.is_contractor_portal_user(organization_id,contract_id))); create policy contractor_requirements_internal on public.contract_document_requirements for all to authenticated using((select private.has_permission(organization_id,'contractors.manage'))) with check((select private.has_permission(organization_id,'contractors.manage')));
create policy contractor_submissions_read on public.contract_document_submissions for select to authenticated using((select private.has_permission(organization_id,'contractors.read')) or (select exists(select 1 from public.contract_document_requirements r where r.id=contract_document_requirement_id and private.is_contractor_portal_user(r.organization_id,r.contract_id)))); create policy contractor_submissions_internal on public.contract_document_submissions for all to authenticated using((select private.has_permission(organization_id,'contractors.manage'))) with check((select private.has_permission(organization_id,'contractors.manage'))); create policy contractor_submissions_portal_insert on public.contract_document_submissions for insert to authenticated with check((select exists(select 1 from public.contract_document_requirements r where r.id=contract_document_requirement_id and private.is_contractor_portal_user(r.organization_id,r.contract_id))));
create policy contractor_evaluations_internal on public.contract_evaluations for all to authenticated using((select private.has_permission(organization_id,'contractors.approve'))) with check((select private.has_permission(organization_id,'contractors.approve'))); create policy contractor_portal_access_own on public.contractor_portal_accesses for select to authenticated using((select exists(select 1 from public.contractor_contacts c where c.id=contractor_contact_id and c.user_id=(select auth.uid()))) or (select private.has_permission(organization_id,'contractors.manage')));
create trigger contracts_links before insert or update on public.contracts for each row execute function private.validate_contractor_links(); create trigger contract_site_links before insert or update on public.contract_site_accesses for each row execute function private.validate_contractor_links(); create trigger worker_links before insert or update on public.contractor_workers for each row execute function private.validate_contractor_links(); create trigger requirement_links before insert or update on public.contract_document_requirements for each row execute function private.validate_contractor_links(); create trigger submission_links before insert or update on public.contract_document_submissions for each row execute function private.validate_contractor_links(); create trigger evaluation_links before insert or update on public.contract_evaluations for each row execute function private.validate_contractor_links(); create trigger portal_links before insert or update on public.contractor_portal_accesses for each row execute function private.validate_contractor_links();
create trigger contracts_audit after insert or update on public.contracts for each row execute function private.capture_core_audit(); create trigger submissions_audit after insert or update on public.contract_document_submissions for each row execute function private.capture_core_audit(); create trigger evaluations_audit after insert or update on public.contract_evaluations for each row execute function private.capture_core_audit(); notify pgrst,'reload schema';
